const correctAnswers = {
    q1: ['java', 'typescript'], // Statically typed languages
    q2: ['javascript', 'css', 'rust'], // Run in browser by default
    q3: ['python', 'nodejs', 'go'] // Backend development languages
};

document.getElementById('quizForm').addEventListener('submit', function(e) {
    e.preventDefault();
    submitQuiz();
});

function submitQuiz() {
    const userAnswers = {
        q1: getCheckedValues('q1'),
        q2: getCheckedValues('q2'),
        q3: getCheckedValues('q3')
    };

    const results = calculateResults(userAnswers);
    displayResults(results);
}

function getCheckedValues(questionName) {
    const checkboxes = document.querySelectorAll(`input[name="${questionName}"]:checked`);
    return Array.from(checkboxes).map(cb => cb.value);
}

function calculateResults(userAnswers) {
    const results = [];
    const questions = [
        { id: 'q1', text: 'Which of the following are statically typed languages?' },
        { id: 'q2', text: 'Which languages run in the browser by default?' },
        { id: 'q3', text: 'Which languages are commonly used for backend development?' }
    ];

    let totalCorrect = 0;

    questions.forEach(question => {
        const correct = correctAnswers[question.id];
        const user = userAnswers[question.id];

        // Check if the user's answers match exactly (same items, no more, no less)
        const isCorrect = correct.length === user.length && 
                         correct.every(item => user.includes(item));

        if (isCorrect) {
            totalCorrect++;
        }

        results.push({
            question: question.text,
            correct: correct,
            user: user,
            isCorrect: isCorrect
        });
    });

    return {
        results: results,
        score: totalCorrect,
        total: questions.length
    };
}

function displayResults(data) {
    const quizForm = document.getElementById('quizForm');
    const resultsSection = document.getElementById('results');
    const resultsContent = document.getElementById('resultsContent');

    let html = `<div class="score-summary" style="text-align: center; margin-bottom: 20px; padding-bottom: 20px; border-bottom: 2px solid #667eea;">
        <h3 style="color: #333; font-size: 20px;">Your Score: ${data.score} / ${data.total}</h3>
        <p style="color: #666; font-size: 16px; margin-top: 8px;">${Math.round((data.score / data.total) * 100)}%</p>
    </div>`;

    html += '<div>';
    data.results.forEach((result, index) => {
        const answerText = result.user.length > 0 
            ? result.user.join(', ') 
            : '<em>No answers selected</em>';
        const correctAnswerText = result.correct.join(', ');
        const statusClass = result.isCorrect ? 'result-correct' : 'result-incorrect';
        const statusText = result.isCorrect ? '✓ Correct' : '✗ Incorrect';

        html += `
            <div class="result-item">
                <div class="result-question">Question ${index + 1}: ${result.question}</div>
                <div class="result-answer"><strong>Your answer:</strong> ${answerText}</div>
                <div class="result-answer"><strong>Correct answer:</strong> ${correctAnswerText}</div>
                <div class="result-answer ${statusClass}"><strong>${statusText}</strong></div>
            </div>
        `;
    });
    html += '</div>';

    resultsContent.innerHTML = html;
    quizForm.style.display = 'none';
    resultsSection.style.display = 'block';
}
